e.results.creditRating : 'N/A', performance: performance, insights: insights }; } _ratingLabel(name) { var map = { 'Exemplary Climate CFO': 'rating_exemplary', 'Strong Execution': 'rating_strong', 'Adequate Strategy': 'rating_adequate', 'Needs Improvement': 'rating_needs_improvement' }; return window.mySimulation.t(map[name] || 'rating_needs_improvement'); } getHint(state, results) { if (!results) return null; if (results.roundScore < 30) return window.mySimulation.t('hint_low_score'); if (state.domainState.debtToEbitda > 3.5) return window.mySimulation.t('hint_debt_high'); if (state.domainState.investorConfidence < 40) return window.mySimulation.t('hint_low_confidence'); if (state.domainState.activistSatisfaction < 25) return window.mySimulation.t('hint_activist_pressure'); if (state.domainState.emissions > 4.0 && state.currentPeriod >= 3) return window.mySimulation.t('hint_slow_reduction'); return null; } getHistoryTableConfig() { return [ { key: 'results.roundScore', label: 'Round Score', i18nKey: 'col_score' }, { key: 'results.emissions', label: 'Emissions (Mt)', i18nKey: 'col_emissions' }, { key: 'results.cash', label: 'Cash ($M)', i18nKey: 'col_cash', formatter: function(v) { return '$' + v.toLocaleString() + 'M'; } }, { key: 'results.debtToEbitda', label: 'Debt/EBITDA', i18nKey: 'col_debt', formatter: function(v) { return v + 'x'; } }, { key: 'results.creditRating', label: 'Credit Rating', i18nKey: 'col_credit' }, { key: 'results.investorConfidence', label: 'Investor Conf.', i18nKey: 'col_investor', formatter: function(v) { return v + '%'; } } ]; } getPresets() { return null; } getTranslations() { return { en: { title: `ClimateCFO: Climate Transition Finance`, subtitle: `Aceros del Sur S.A. — CFO Strategic Challenge`, round_label: `Round`, period_of: `of`, cash_label: `Cash Position ($M)`, emissions_label: `Emissions (MtCO2e)`, debt_ratio_label: `Debt-to-EBITDA`, credit_label: `Credit Rating`, investor_conf_label: `Investor Confidence`, green_revenue_label: `Green Steel Revenue %`, briefing_heading: `Round Briefing`, events_heading: `Market Events`, decisions_heading: `Your Decisions`, stakeholder_heading: `Stakeholder Reactions`, history_heading: `Decision History`, chart_emissions_title: `Emissions Trajectory`, chart_financial_title: `Financial Health`, decision1_label: `Decision 1`, decision2_label: `Decision 2`, decision3_label: `Decision 3`, decision4_label: `Decision 4`, decision5_label: `Decision 5`, decision6_label: `Decision 6`, submit_btn: `Submit Round`, undo_btn: `Undo Last Round`, all_decisions_warning: `Please make all required decisions before submitting.`, hint_low_score: `Low round score. Consider more ambitious and transparent choices to build stakeholder trust.`, hint_debt_high: `Debt-to-EBITDA exceeds covenant threshold of 3.5x. Prioritize deleveraging or green bond issuance.`, hint_low_confidence: `Investor confidence is critically low. Strengthen ESG reporting and climate commitments.`, hint_activist_pressure: `Activist satisfaction is very low. Risk of AGM opposition and divestment campaigns.`, hint_slow_reduction: `Emissions reduction is behind schedule. Accelerate technology deployment.`, col_score: `Score`, col_emissions: `Emissions (Mt)`, col_cash: `Cash ($M)`, col_debt: `Debt/EBITDA`, col_credit: `Credit Rating`, col_investor: `Investor Conf.`,r1_name:'Emissions Baselining & Materiality Assessment',r1_desc:'<b>Scenario:</b> Your first investor meeting is in 4 weeks. An activist investor letter demands SBTi targets or faces AGM opposition. The climate team completed a preliminary carbon footprint, but Scope 3 data quality is mixed.<br><br><b>Context:</b> Aceros del Sur (AdS) is a $1.4B Latin American steel manufacturer with 4.9 MtCO2e total emissions. EU CBAM threatens export margins. ESG fund managers (30% equity) signal divestment risk without credible TCFD reporting.<br><br><b>Your challenge:</b> Set emissions boundaries, choose reporting standards, define SBTi ambition, and decide on external assurance.',r1d1_label:'Scope 3 Emissions Boundary',r1d1_hint:'Expanding scope raises reported emissions 40% but improves credibility',r1d1o1:'Scope 1-2 Only (lower reported emissions, simpler accounting)',r1d1o2:'Scope 1-2 + Partial Scope 3 (supply chain only, moderate credibility)',r1d1o3:'Full Scope 1-2-3 (highest credibility, complex accounting)',r1d2_label:'SBTi Target Ambition (Scope 1-2 Reduction by 2030)',r1d2_hint:'Activists demand 50%; creditors prefer 25%; operations says even 25% is risky',r1d2o1:'25% Reduction (creditor-friendly, low activist appeal)',r1d2o2:'40% Reduction (balanced approach)',r1d2o3:'50% Reduction (activist-aligned, high capex ~$650M)',r1d3_label:'Reporting Standard',r1d3_hint:'Transparency creates credibility but widens room for critique',r1d3o1:'TCFD Only (voluntary, widely recognized)',r1d3o2:'TCFD + ISSB S1/S2 (comprehensive, mandatory-grade)',r1d3o3:'TCFD + ISSB + GRI (maximum transparency)',r1d4_label:'External Assurance',r1d4_hint:'Costs $500K but signals seriousness to investors and regulators',r1d4o1:'No External Assurance (save cost, lower credibility)',r1d4o2:'Limited Assurance (mid-tier firm, $250K)',r1d4o3:'Full Big 4 Assurance ($500K, highest credibility)',r2_name:'Decarbonization Roadmap & Technology Investment',r2_desc:'<b>Scenario:</b> The board approved your SBTi target at the AGM and now demands a detailed capex roadmap. Three technology pathways are modeled.<br><br><b>Technology Options:</b><br>- Green Hydrogen + DRI: $450M capex, -2.1 MtCO2e, IRR -2%<br>- Electric Arc Furnace (Scrap): $280M capex, -1.2 MtCO2e, IRR +3%<br>- Hybrid Path (50% H2 + 30% EAF): $550M capex, lower tech risk<br><br><b>Challenge:</b> Current blast furnaces are worth $400M book value. Accelerating decarbonization triggers asset write-downs. Debt-to-EBITDA could spike to 3.8x.',r2d1_label:'Technology Path Selection',r2d1_hint:'Green H2 attracts activists but worries creditors; EAF is moderate but may seem insufficient',r2d1o1:'Green Hydrogen + DRI ($450M, highest reduction, highest risk)',r2d1o2:'Electric Arc Furnace ($280M, moderate reduction, faster ROI)',r2d1o3:'Hybrid Path ($550M, balanced reduction, lower tech risk)',r2d2_label:'Capex Phasing Strategy',r2d2_hint:'Front-loading accelerates progress but strains credit metrics',r2d2o1:'Front-Load (60% in Years 3-5, aggressive timeline)',r2d2o2:'Balanced Phasing (even spread over 8 years)',r2d2o3:'Back-Load (70% in Years 6-10, preserve near-term EBITDA)',r2d3_label:'Stranded Asset Strategy',r2d3_hint:'Blast furnaces: $400M book value. Early retirement creates write-downs',r2d3o1:'Immediate Impairment ($250M write-down, transparent)',r2d3o2:'Phased Impairment (over 5 years, smoother earnings)',r2d3o3:'Delay Impairment (run assets until forced retirement)',r2d4_label:'Capex Funding Strategy',r2d4_hint:'Funding mix affects debt ratios and credit rating trajectory',r2d4o1:'Green Bond Issuance (ESG capital, lower coupon, audit required)',r2d4o2:'Sustainability-Linked Loan (rate tied to KPI performance)',r2d4o3:'Non-Core Asset Divestiture + Conventional Debt',r3_name:'Climate Finance Instruments & Regulatory Compliance',r3_desc:'<b>Scenario:</b> Mexico announces a carbon pricing mechanism at $40/ton starting 2027. EU CBAM enters Phase 2 with higher tariffs. Your capex plan needs financing.<br><br><b>Financial Context:</b><br>- Green bond market: strong ESG demand, coupon 4.2% vs 4.95% conventional<br>- Carbon credit potential: 500K tons at $20-30/ton = $10-15M annually<br>- Mexican carbon tax exposure: $112M annually at current emissions<br>- CBAM tariff: rising to ~18M EUR annually<br><br><b>Challenge:</b> Balance financing costs, regulatory compliance, and risk transfer.',r3d1_label:'Green Bond Strategy',r3d1_hint:'Attracts ESG investors but requires independent auditor verification',r3d1o1:'Issue EUR 200M Green Bond (maximum ESG signal)',r3d1o2:'Issue EUR 100M Green Bond (moderate approach)',r3d1o3:'Skip Green Bond (use conventional financing only)',r3d2_label:'Carbon Credit Monetization',r3d2_hint:'Decarbonization generates credits but verification adds cost and market is volatile',r3d2o1:'Aggressive Monetization (sell 500K tons, maximize revenue)',r3d2o2:'Moderate Monetization (sell 250K tons, retain buffer)',r3d2o3:'Retain All Credits (use for internal compliance)',r3d3_label:'Mexican Carbon Tax Strategy',r3d3_hint:'Exposure: $112M at $40/ton. Lobby, offset, or pass through to customers?',r3d3o1:'Lobby for Industry Carve-outs (reduce exposure, political risk)',r3d3o2:'Invest in Certified Offsets (reduce net tax, market risk)',r3d3o3:'Pass Costs to Customers (protect margins, lose competitiveness)',r3d4_label:'CBAM Tariff Response',r3d4_hint:'EU exports are 40% of revenue. CBAM directly impacts margins',r3d4o1:'Negotiate Premium Green Steel Contracts with EU Customers',r3d4o2:'Invest in EU Production Facility (tariff-exempt, high capex)',r3d4o3:'Absorb Tariff Cost (maintain volume, lower margin)',r3d5_label:'Climate Insurance',r3d5_hint:'Physical asset insurance costs $5-8M annually. Peru flood risk is 5% annually',r3d5o1:'Comprehensive Climate Insurance ($8M/year, full coverage)',r3d5o2:'Basic Coverage ($5M/year, major events only)',r3d5o3:'Self-Insure (save premium, accept risk)',r4_name:'TCFD/ISSB Reporting & Scenario Analysis',r4_desc:'<b>Scenario:</b> AdS must file annual report with TCFD and ISSB S1/S2 disclosures. Regulators demand climate scenario analysis at 1.5C, 2C, and 3C warming pathways.<br><br><b>Crisis Event:</b> Severe flooding hits the Peru facility (your second-largest), forcing temporary production suspension. Loss estimate: $25M.<br><br><b>Scenario Impacts:</b><br>- 1.5C: $400M capex acceleration, -15% EBITDA, but green steel premium<br>- 2C: Baseline (aligned with your targets)<br>- 3C: $150M capex savings but stranded asset risk and market share loss<br><br><b>Challenge:</b> Transparent disclosure without spooking investors. Quantify physical and transition risks.',r4d1_label:'Scenario Weighting for Disclosure',r4d1_hint:'How you weight scenarios shapes investor perception and capital allocation',r4d1o1:'Emphasize 1.5C Pathway (activist-aligned, high capex signal)',r4d1o2:'Balanced Weighting (2C primary, others secondary)',r4d1o3:'Emphasize 3C Pathway (lower cost, board-skeptic preferred)',r4d2_label:'Physical Risk Response (Peru Flood)',r4d2_hint:'The flood exposed supply chain vulnerability. Annual flood risk is 5%',r4d2o1:'Rebuild with Climate Resilience ($40M, flood-proof)',r4d2o2:'Standard Rebuild + Insurance ($25M rebuild + $8M/yr insurance)',r4d2o3:'Relocate to Lower-Risk Site ($60M, long-term protection)',r4d3_label:'ISSB Disclosure Depth',r4d3_hint:'Transparency creates accountability; ensure delivery matches promises',r4d3o1:'Maximum Disclosure (all scenarios, full financial quantification)',r4d3o2:'Standard Disclosure (meet requirements, forward-looking disclaimers)',r4d3o3:'Minimum Required Disclosure (reduce exposure to critique)',r4d4_label:'Investor Communication Strategy',r4d4_hint:'ESG funds want ambition; skeptics want stability. How do you message?',r4d4o1:'Dual Narrative (tailor messaging to each investor segment)',r4d4o2:'Unified Ambitious Message (climate leadership positioning)',r4d4o3:'Unified Conservative Message (financial prudence emphasis)',r5_name:'Board Presentation & Strategic Defense',r5_desc:'<b>Scenario:</b> The 10-year strategy review and AGM. Present your climate transition plan to the full board and activist investors.<br><br><b>Progress So Far:</b> Emissions down ~35% (tracking to 50% target), green bond issued, hydrogen pilot operating, TCFD reporting praised by analysts.<br><br><b>Headwinds:</b><br>- Metal prices fell 20% (EBITDA down $40M)<br>- Mexican carbon tax ramped faster than expected (+$8M cost)<br>- Activists demand climate targets in executive compensation<br>- Founder/board chair questions if capex was overkill<br>- Credit rating agency: "stable" outlook (vs. hoped-for "positive")<br><br><b>Challenge:</b> Defend your strategy, set next-decade targets, and align all stakeholders.',r5d1_label:'Transition Capex Defense',r5d1_hint:'Was $450M+ justified? Board skeptics and activists both need convincing',r5d1o1:'Aggressive Defense (emphasize avoided stranded assets + green premium)',r5d1o2:'Balanced Defense (acknowledge costs, highlight strategic positioning)',r5d1o3:'Concede Some Concerns (admit timing could improve, show adaptability)',r5d2_label:'Executive Compensation Linkage',r5d2_hint:'Tying bonuses to climate KPIs: accountability vs. gaming risk',r5d2o1:'Full Climate KPI Linkage (30% of bonus tied to emissions targets)',r5d2o2:'Partial Linkage (15% of bonus, balanced with financial KPIs)',r5d2o3:'No Explicit Climate Linkage (maintain traditional financial metrics)',r5d3_label:'Next-Decade Targets (2035-2040)',r5d3_hint:'Set ambitious targets to attract capital vs. achievable ones to maintain credibility',r5d3o1:'Net-Zero by 2045 (industry-leading, highest ambition)',r5d3o2:'Net-Zero by 2050 (Paris-aligned, standard timeline)',r5d3o3:'Incremental Targets Only (avoid net-zero commitment)',r5d4_label:'Capital Allocation: Dividends vs. Green Investment',r5d4_hint:'Shareholders expect returns; technology R&D secures future competitiveness',r5d4o1:'Resume Full Dividends (satisfy shareholders, reduce green R&D)',r5d4o2:'Modest Dividends + Continued Green Investment (balanced)',r5d4o3:'Reinvest All in Green Technology (maximize transition speed)',r5d5_label:'Strategic Positioning Narrative',r5d5_hint:'How does AdS position itself for the next decade?',r5d5o1:'LATAM Climate Leader (premium brand, attract ESG capital)',r5d5o2:'Pragmatic Transitioner (balanced messaging, broad appeal)',r5d5o3:'Cost-Competitive Green Producer (efficiency focus)',n1:'Full Scope 1-2-3 accounting adopted. Credibility boosted with ESG investors.<br>',n2:'Partial Scope 3 boundary. Moderate credibility gain.<br>',n3:'Scope 1-2 only boundary. Activists flag this as inadequate.<br>',n4:'50% SBTi target announced. Activists celebrate. Creditors cautious about $650M capex implication.<br>',n5:'40% SBTi target. Balanced reaction from stakeholders.<br>',n6:'25% SBTi target. Creditors comfortable but activists threaten AGM opposition.<br>',n7:'Maximum reporting transparency adopted (TCFD + ISSB + GRI).<br>',n8:'TCFD + ISSB reporting framework selected.<br>',n9:'TCFD-only reporting. Adequate but may fall behind regulatory requirements.<br>',n10:'Big 4 assurance engagement signals commitment. Cost: $500K.<br>',n11:'Limited assurance provides moderate credibility boost.<br>',n12:'No external assurance. Investors question data reliability.<br>',n13:'Green Hydrogen + DRI path selected. Bold move. Capex: $450M committed.<br>',n14:'Electric Arc Furnace path selected. Moderate capex: $280M.<br>',n15:'Hybrid path (H2 + EAF). Diversified technology risk. Capex: $550M.<br>',n16:'Front-loaded capex accelerates emissions reduction but strains near-term credit.<br>',n17:'Balanced phasing maintains steady progress.<br>',n18:'Back-loaded capex protects near-term EBITDA. Activists question commitment pace.<br>',n19:'Immediate asset impairment: $250M write-down. Transparent but painful.<br>',n20:'Phased impairment over 5 years. Smoother earnings impact.<br>',n21:'Impairment delayed. Risk of larger surprise write-down later.<br>',n22:'Green bond issuance planned. ESG investor demand is strong.<br>',n23:'Sustainability-linked loan negotiated. Rate tied to KPI performance.<br>',n24:'Non-core asset divestiture + conventional debt. Straightforward but no ESG signal.<br>',n25:'EUR 200M green bond issued at 4.2% coupon. Strong ESG investor demand.<br>',n26:'EUR 100M green bond issued. Moderate ESG capital raised.<br>',n27:'No green bond. Missed opportunity for ESG capital access.<br>',n28:'Aggressive carbon credit monetization: $15M revenue. Market volatility risk.<br>',n29:'Moderate credit sales: $8M revenue. Buffer retained for compliance.<br>',n30:'Credits retained for internal compliance. No market revenue.<br>',n31:'Lobbying for carve-outs. Partial success: exposure reduced to $70M. Political risk remains.<br>',n32:'Offset investment strategy. Net exposure: $85M. Improves climate narrative.<br>',n33:'Costs passed to customers. Margin protected but competitiveness weakened.<br>',n34:'Premium green steel contracts secured with EU customers. Revenue upside: $20M.<br>',n35:'EU production investment initiated. High capex now; tariff-exempt revenue later.<br>',n36:'Absorbing CBAM tariff. Volume maintained but margins compressed.<br>',n37:'Comprehensive climate insurance purchased. $8M/year for full coverage.<br>',n38:'Basic climate insurance. Major events covered. $5M/year.<br>',n39:'Self-insured. Premium saved but physical risk fully retained.<br>',n40:'Peru flood damage: $25M. Insurance covers $20M. Net loss: $5M.<br>',n41:'Peru flood damage: $25M. Basic insurance covers $13M. Net loss: $12M.<br>',n42:'Peru flood damage: $25M. No insurance. Full loss absorbed.<br>',n43:'1.5C-aligned scenario emphasis. Strong climate leadership signal.<br>',n44:'Balanced scenario weighting. Credible and pragmatic.<br>',n45:'3C emphasis. Board skeptics pleased but activists alarmed. Divestment risk rises.<br>',n46:'Climate-resilient rebuild in Peru. $40M investment for long-term protection.<br>',n47:'Standard rebuild + enhanced insurance. $25M rebuild cost.<br>',n48:'Peru facility relocation to lower-risk site. $60M but eliminates flood exposure.<br>',n49:'Maximum ISSB disclosure. Praised by ESG analysts. Sets industry benchmark.<br>',n50:'Standard ISSB disclosure. Meets requirements, avoids unnecessary exposure.<br>',n51:'Minimum disclosure. Regulators flag gaps. Activist criticism intensifies.<br>',n52:'Dual narrative strategy. Tailored messaging resonates with each audience.<br>',n53:'Unified ambitious messaging. Climate leadership brand solidifies.<br>',n54:'Conservative messaging. Creditors reassured but activist frustration grows.<br>',n55:'Aggressive capex defense with data on avoided stranded assets and green premium value.<br>',n56:'Balanced defense acknowledges costs while highlighting strategic gains.<br>',n57:'Conceding timing concerns shows humility. Mixed reactions.<br>',n58:'30% of executive bonus tied to climate KPIs. Strong accountability signal.<br>',n59:'15% bonus linkage to climate KPIs. Balanced approach.<br>',n60:'No climate linkage in compensation. Activists view this as governance failure.<br>',n61:'Net-Zero by 2045 commitment. Industry-leading ambition attracts ESG capital.<br>',n62:'Net-Zero by 2050. Paris-aligned. Credible and expected.<br>',n63:'No net-zero commitment. Activists escalate. ESG fund divestment risk acute.<br>',n64:'Full dividend resumption. Shareholders satisfied. Green R&D reduced.<br>',n65:'Modest dividends + continued green investment. Balanced capital allocation.<br>',n66:'Full reinvestment in green technology. Maximizes transition speed but tests shareholder patience.<br>',n67:'Positioned as LATAM Climate Leader. Premium brand commands ESG capital flows.<br>',n68:'Pragmatic transitioner positioning. Broad stakeholder appeal.<br>',n69:'Cost-competitive green producer. Efficiency-first narrative.<br>',select_placeholder:'-- Select --',chart_emissions_dataset:'Total Emissions (MtCO2e)',chart_emissions_axis:'MtCO2e',chart_cash_dataset:'Cash Position ($M)',chart_investor_dataset:'Investor Confidence (%)',chart_financial_full_title:'Financial Health & Stakeholder Confidence',rating_exemplary:'Exemplary Climate CFO',rating_strong:'Strong Execution',rating_adequate:'Adequate Strategy',rating_needs_improvement:'Needs Improvement',insight_emissions_excellent:'Excellent emissions reduction of {pct}% achieved. On track for SBTi targets.',insight_emissions_moderate:'Moderate emissions reduction of {pct}%. Consider accelerating decarbonization investments.',insight_emissions_low:'Emissions reduction of only {pct}%. Strategy may need fundamental rethinking.',insight_investor_strong:'Strong investor confidence built through credible climate strategy and transparent reporting.',insight_investor_weak:'Investor confidence remains a challenge. Consider stronger ESG engagement and reporting.',insight_credit_improved:'Credit rating improved through prudent capital management during transition.' }, es: { title: `ClimateCFO: Finanzas de Transición Climática`, subtitle: `Aceros del Sur S.A. — Desafío Estratégico del CFO`, round_label: `Ronda`, period_of: `de`, cash_label: `Posición de Caja ($M)`, emissions_label: `Emisiones (MtCO2e)`, debt_ratio_label: `Deuda/EBITDA`, credit_label: `Calificación Crediticia`, investor_conf_label: `Confianza del Inversor`, green_revenue_label: `% Ingresos Acero Verde`, briefing_heading: `Informe de Ronda`, events_heading: `Eventos del Mercado`, decisions_heading: `Tus Decisiones`, stakeholder_heading: `Reacciones de los Grupos de Interés`, history_heading: `Historial de Decisiones`, chart_emissions_title: `Trayectoria de Emisiones`, chart_financial_title: `Salud Financiera`, decision1_label: `Decisión 1`, decision2_label: `Decisión 2`, decision3_label: `Decisión 3`, decision4_label: `Decisión 4`, decision5_label: `Decisión 5`, decision6_label: `Decisión 6`, submit_btn: `Enviar Ronda`, undo_btn: `Deshacer Última Ronda`, all_decisions_warning: `Por favor tome todas las decisiones requeridas antes de enviar.`, hint_low_score: `Puntuación baja. Considere opciones más ambiciosas y transparentes para generar confianza.`, hint_debt_high: `La relación Deuda/EBITDA supera el umbral de 3.5x. Priorice el desapalancamiento.`, hint_low_confidence: `La confianza del inversor es criticamente baja. Fortalezca los reportes ESG.`, hint_activist_pressure: `Satisfacción de activistas muy baja. Riesgo de oposición en la asamblea.`, hint_slow_reduction: `La reducción de emisiones va retrasada. Acelere el despliegue tecnológico.`, col_score: `Puntuación`, col_emissions: `Emisiones (Mt)`, col_cash: `Caja ($M)`, col_debt: `Deuda/EBITDA`, col_credit: `Calificación`, col_investor: `Conf. Inversor`,r1_name:'Línea Base de Emisiones y Evaluación de Materialidad',r1_desc:'<b>Escenario:</b> Su primera reunión con inversores es en 4 semanas. Una carta de un inversor activista exige objetivos SBTi o enfrenta oposición en la asamblea. El equipo de clima completó una huella de carbono preliminar, pero la calidad de los datos de Alcance 3 es desigual.<br><br><b>Contexto:</b> Aceros del Sur (AdS) es un fabricante de acero latinoamericano de 1.4B$ con 4.9 MtCO2e de emisiones totales. El CBAM de la UE amenaza los márgenes de exportación. Los gestores de fondos ESG (30% del capital) señalan riesgo de desinversión sin un reporte TCFD creíble.<br><br><b>Su desafío:</b> Defina los límites de emisiones, elija estándares de reporte, establezca la ambición SBTi y decida sobre la verificación externa.',r1d1_label:'Límite de Emisiones de Alcance 3',r1d1_hint:'Ampliar el alcance eleva las emisiones reportadas un 40% pero mejora la credibilidad',r1d1o1:'Solo Alcance 1-2 (menores emisiones reportadas, contabilidad más simple)',r1d1o2:'Alcance 1-2 + Alcance 3 Parcial (solo cadena de suministro, credibilidad moderada)',r1d1o3:'Alcance 1-2-3 Completo (máxima credibilidad, contabilidad compleja)',r1d2_label:'Ambición del Objetivo SBTi (Reducción de Alcance 1-2 para 2030)',r1d2_hint:'Los activistas exigen 50%; los acreedores prefieren 25%; operaciones dice que incluso 25% es riesgoso',r1d2o1:'Reducción del 25% (favorable a acreedores, poco atractivo para activistas)',r1d2o2:'Reducción del 40% (enfoque equilibrado)',r1d2o3:'Reducción del 50% (alineado con activistas, alto capex ~650M$)',r1d3_label:'Estándar de Reporte',r1d3_hint:'La transparencia genera credibilidad pero amplía el margen para la crítica',r1d3o1:'Solo TCFD (voluntario, ampliamente reconocido)',r1d3o2:'TCFD + ISSB S1/S2 (integral, de nivel obligatorio)',r1d3o3:'TCFD + ISSB + GRI (máxima transparencia)',r1d4_label:'Verificación Externa',r1d4_hint:'Cuesta 500K$ pero señala seriedad a inversores y reguladores',r1d4o1:'Sin Verificación Externa (ahorra costo, menor credibilidad)',r1d4o2:'Verificación Limitada (firma de nivel medio, 250K$)',r1d4o3:'Verificación Completa Big 4 (500K$, máxima credibilidad)',r2_name:'Hoja de Ruta de Descarbonización e Inversión Tecnológica',r2_desc:'<b>Escenario:</b> La junta aprobó su objetivo SBTi en la asamblea y ahora exige una hoja de ruta de capex detallada. Se modelan tres trayectorias tecnológicas.<br><br><b>Opciones Tecnológicas:</b><br>- Hidrógeno Verde + DRI: 450M$ de capex, -2.1 MtCO2e, TIR -2%<br>- Horno de Arco Eléctrico (Chatarra): 280M$ de capex, -1.2 MtCO2e, TIR +3%<br>- Ruta Híbrida (50% H2 + 30% EAF): 550M$ de capex, menor riesgo tecnológico<br><br><b>Desafío:</b> Los altos hornos actuales tienen un valor contable de 400M$. Acelerar la descarbonización desencadena castigos de activos. La Deuda/EBITDA podría dispararse a 3.8x.',r2d1_label:'Selección de Ruta Tecnológica',r2d1_hint:'El H2 verde atrae a los activistas pero preocupa a los acreedores; el EAF es moderado pero puede parecer insuficiente',r2d1o1:'Hidrógeno Verde + DRI (450M$, mayor reducción, mayor riesgo)',r2d1o2:'Horno de Arco Eléctrico (280M$, reducción moderada, retorno más rápido)',r2d1o3:'Ruta Híbrida (550M$, reducción equilibrada, menor riesgo tecnológico)',r2d2_label:'Estrategia de Fases del Capex',r2d2_hint:'Adelantar el gasto acelera el progreso pero tensiona las métricas crediticias',r2d2o1:'Adelantado (60% en Años 3-5, cronograma agresivo)',r2d2o2:'Fases Equilibradas (distribución uniforme en 8 años)',r2d2o3:'Postergado (70% en Años 6-10, preserva el EBITDA a corto plazo)',r2d3_label:'Estrategia de Activos Varados',r2d3_hint:'Altos hornos: 400M$ de valor contable. El retiro anticipado genera castigos contables',r2d3o1:'Deterioro Inmediato (castigo de 250M$, transparente)',r2d3o2:'Deterioro Gradual (en 5 años, resultados más suaves)',r2d3o3:'Retrasar el Deterioro (operar los activos hasta el retiro forzoso)',r2d4_label:'Estrategia de Financiamiento del Capex',r2d4_hint:'La mezcla de financiamiento afecta los ratios de deuda y la trayectoria de la calificación crediticia',r2d4o1:'Emisión de Bono Verde (capital ESG, cupón más bajo, requiere auditoría)',r2d4o2:'Préstamo Vinculado a Sostenibilidad (tasa ligada al desempeño de KPIs)',r2d4o3:'Desinversión de Activos No Esenciales + Deuda Convencional',r3_name:'Instrumentos de Financiamiento Climático y Cumplimiento Regulatorio',r3_desc:'<b>Escenario:</b> México anuncia un mecanismo de precio al carbono de 40$/tonelada a partir de 2027. El CBAM de la UE entra en la Fase 2 con aranceles más altos. Su plan de capex necesita financiamiento.<br><br><b>Contexto Financiero:</b><br>- Mercado de bonos verdes: fuerte demanda ESG, cupón 4.2% frente a 4.95% convencional<br>- Potencial de créditos de carbono: 500K toneladas a 20-30$/tonelada = 10-15M$ anuales<br>- Exposición al impuesto al carbono mexicano: 112M$ anuales con las emisiones actuales<br>- Arancel CBAM: subiendo a ~18M EUR anuales<br><br><b>Desafío:</b> Equilibre los costos de financiamiento, el cumplimiento regulatorio y la transferencia de riesgo.',r3d1_label:'Estrategia de Bono Verde',r3d1_hint:'Atrae a inversores ESG pero requiere verificación de auditor independiente',r3d1o1:'Emitir Bono Verde de 200M EUR (máxima señal ESG)',r3d1o2:'Emitir Bono Verde de 100M EUR (enfoque moderado)',r3d1o3:'Omitir el Bono Verde (usar solo financiamiento convencional)',r3d2_label:'Monetización de Créditos de Carbono',r3d2_hint:'La descarbonización genera créditos pero la verificación añade costo y el mercado es volátil',r3d2o1:'Monetización Agresiva (vender 500K toneladas, maximizar ingresos)',r3d2o2:'Monetización Moderada (vender 250K toneladas, mantener reserva)',r3d2o3:'Retener Todos los Créditos (usar para cumplimiento interno)',r3d3_label:'Estrategia ante el Impuesto al Carbono Mexicano',r3d3_hint:'Exposición: 112M$ a 40$/tonelada. ¿Cabildear, compensar o trasladar a los clientes?',r3d3o1:'Cabildear por Exenciones Sectoriales (reduce exposición, riesgo político)',r3d3o2:'Invertir en Compensaciones Certificadas (reduce el impuesto neto, riesgo de mercado)',r3d3o3:'Trasladar Costos a Clientes (protege márgenes, pierde competitividad)',r3d4_label:'Respuesta al Arancel CBAM',r3d4_hint:'Las exportaciones a la UE son el 40% de los ingresos. El CBAM impacta directamente los márgenes',r3d4o1:'Negociar Contratos Premium de Acero Verde con Clientes de la UE',r3d4o2:'Invertir en Planta de Producción en la UE (exenta de aranceles, alto capex)',r3d4o3:'Absorber el Costo del Arancel (mantiene volumen, menor margen)',r3d5_label:'Seguro Climático',r3d5_hint:'El seguro de activos físicos cuesta 5-8M$ anuales. El riesgo de inundación en Perú es del 5% anual',r3d5o1:'Seguro Climático Integral (8M$/año, cobertura completa)',r3d5o2:'Cobertura Básica (5M$/año, solo eventos mayores)',r3d5o3:'Autoasegurarse (ahorra la prima, acepta el riesgo)',r4_name:'Reporte TCFD/ISSB y Análisis de Escenarios',r4_desc:'<b>Escenario:</b> AdS debe presentar el reporte anual con divulgaciones TCFD e ISSB S1/S2. Los reguladores exigen análisis de escenarios climáticos a trayectorias de calentamiento de 1.5C, 2C y 3C.<br><br><b>Evento de Crisis:</b> Inundaciones severas golpean la planta de Perú (su segunda más grande), forzando una suspensión temporal de producción. Pérdida estimada: 25M$.<br><br><b>Impactos por Escenario:</b><br>- 1.5C: aceleración de capex de 400M$, -15% EBITDA, pero prima de acero verde<br>- 2C: Escenario base (alineado con sus objetivos)<br>- 3C: ahorro de capex de 150M$ pero riesgo de activos varados y pérdida de cuota de mercado<br><br><b>Desafío:</b> Divulgación transparente sin asustar a los inversores. Cuantifique los riesgos físicos y de transición.',r4d1_label:'Ponderación de Escenarios para la Divulgación',r4d1_hint:'Cómo pondera los escenarios moldea la percepción de los inversores y la asignación de capital',r4d1o1:'Enfatizar la Trayectoria 1.5C (alineado con activistas, señal de alto capex)',r4d1o2:'Ponderación Equilibrada (2C principal, otros secundarios)',r4d1o3:'Enfatizar la Trayectoria 3C (menor costo, preferido por escépticos de la junta)',r4d2_label:'Respuesta al Riesgo Físico (Inundación en Perú)',r4d2_hint:'La inundación expuso la vulnerabilidad de la cadena de suministro. El riesgo anual de inundación es del 5%',r4d2o1:'Reconstruir con Resiliencia Climática (40M$, a prueba de inundaciones)',r4d2o2:'Reconstrucción Estándar + Seguro (25M$ reconstrucción + 8M$/año seguro)',r4d2o3:'Reubicar a un Sitio de Menor Riesgo (60M$, protección a largo plazo)',r4d3_label:'Profundidad de la Divulgación ISSB',r4d3_hint:'La transparencia genera rendición de cuentas; asegúrese de que los resultados coincidan con las promesas',r4d3o1:'Divulgación Máxima (todos los escenarios, cuantificación financiera completa)',r4d3o2:'Divulgación Estándar (cumple requisitos, con salvedades prospectivas)',r4d3o3:'Divulgación Mínima Requerida (reduce la exposición a críticas)',r4d4_label:'Estrategia de Comunicación con Inversores',r4d4_hint:'Los fondos ESG quieren ambición; los escépticos quieren estabilidad. ¿Cómo comunica?',r4d4o1:'Narrativa Dual (adapta el mensaje a cada segmento de inversores)',r4d4o2:'Mensaje Ambicioso Unificado (posicionamiento de liderazgo climático)',r4d4o3:'Mensaje Conservador Unificado (énfasis en prudencia financiera)',r5_name:'Presentación a la Junta y Defensa Estratégica',r5_desc:'<b>Escenario:</b> La revisión estratégica de 10 años y la asamblea general. Presente su plan de transición climática a toda la junta e inversores activistas.<br><br><b>Progreso hasta Ahora:</b> Emisiones reducidas ~35% (en camino al objetivo del 50%), bono verde emitido, planta piloto de hidrógeno operando, reporte TCFD elogiado por analistas.<br><br><b>Vientos en Contra:</b><br>- Los precios de los metales cayeron 20% (EBITDA cae 40M$)<br>- El impuesto al carbono mexicano subió más rápido de lo esperado (+8M$ de costo)<br>- Los activistas exigen objetivos climáticos en la compensación ejecutiva<br>- El fundador/presidente de la junta cuestiona si el capex fue excesivo<br>- La agencia calificadora: perspectiva "estable" (frente a la esperada "positiva")<br><br><b>Desafío:</b> Defienda su estrategia, fije objetivos para la próxima década y alinee a todos los grupos de interés.',r5d1_label:'Defensa del Capex de Transición',r5d1_hint:'¿Se justificaron los 450M$+? Tanto los escépticos de la junta como los activistas necesitan convencerse',r5d1o1:'Defensa Agresiva (enfatiza activos varados evitados + prima verde)',r5d1o2:'Defensa Equilibrada (reconoce costos, destaca el posicionamiento estratégico)',r5d1o3:'Conceder Algunas Preocupaciones (admite que el momento pudo mejorar, muestra adaptabilidad)',r5d2_label:'Vinculación de la Compensación Ejecutiva',r5d2_hint:'Vincular los bonos a KPIs climáticos: rendición de cuentas frente a riesgo de manipulación',r5d2o1:'Vinculación Total a KPIs Climáticos (30% del bono ligado a objetivos de emisiones)',r5d2o2:'Vinculación Parcial (15% del bono, equilibrado con KPIs financieros)',r5d2o3:'Sin Vinculación Climática Explícita (mantiene métricas financieras tradicionales)',r5d3_label:'Objetivos para la Próxima Década (2035-2040)',r5d3_hint:'Fijar objetivos ambiciosos para atraer capital frente a objetivos alcanzables para mantener la credibilidad',r5d3o1:'Cero Neto para 2045 (líder del sector, máxima ambición)',r5d3o2:'Cero Neto para 2050 (alineado con París, cronograma estándar)',r5d3o3:'Solo Objetivos Incrementales (evita el compromiso de cero neto)',r5d4_label:'Asignación de Capital: Dividendos frente a Inversión Verde',r5d4_hint:'Los accionistas esperan retornos; la I+D tecnológica asegura la competitividad futura',r5d4o1:'Reanudar Dividendos Completos (satisface a accionistas, reduce la I+D verde)',r5d4o2:'Dividendos Modestos + Inversión Verde Continuada (equilibrado)',r5d4o3:'Reinvertir Todo en Tecnología Verde (maximiza la velocidad de transición)',r5d5_label:'Narrativa de Posicionamiento Estratégico',r5d5_hint:'¿Cómo se posiciona AdS para la próxima década?',r5d5o1:'Líder Climático de LATAM (marca premium, atrae capital ESG)',r5d5o2:'Transición Pragmática (mensaje equilibrado, amplio atractivo)',r5d5o3:'Productor Verde Competitivo en Costos (enfoque en eficiencia)',n1:'Se adoptó la contabilidad completa de Alcance 1-2-3. Credibilidad reforzada ante los inversores ESG.<br>',n2:'Límite parcial de Alcance 3. Ganancia moderada de credibilidad.<br>',n3:'Límite solo de Alcance 1-2. Los activistas lo señalan como inadecuado.<br>',n4:'Se anunció el objetivo SBTi del 50%. Los activistas celebran. Los acreedores cautelosos por la implicación de 650M$ en capex.<br>',n5:'Objetivo SBTi del 40%. Reacción equilibrada de los grupos de interés.<br>',n6:'Objetivo SBTi del 25%. Los acreedores están cómodos pero los activistas amenazan con oponerse en la asamblea.<br>',n7:'Se adoptó la máxima transparencia de reporte (TCFD + ISSB + GRI).<br>',n8:'Se seleccionó el marco de reporte TCFD + ISSB.<br>',n9:'Reporte solo TCFD. Adecuado pero podría quedar rezagado frente a los requisitos regulatorios.<br>',n10:'La verificación con una Big 4 señala compromiso. Costo: 500K$.<br>',n11:'La verificación limitada aporta un impulso moderado de credibilidad.<br>',n12:'Sin verificación externa. Los inversores cuestionan la fiabilidad de los datos.<br>',n13:'Se seleccionó la ruta de Hidrógeno Verde + DRI. Movimiento audaz. Capex comprometido: 450M$.<br>',n14:'Se seleccionó la ruta de Horno de Arco Eléctrico. Capex moderado: 280M$.<br>',n15:'Ruta híbrida (H2 + EAF). Riesgo tecnológico diversificado. Capex: 550M$.<br>',n16:'El capex adelantado acelera la reducción de emisiones pero tensiona el crédito a corto plazo.<br>',n17:'Las fases equilibradas mantienen un progreso constante.<br>',n18:'El capex postergado protege el EBITDA a corto plazo. Los activistas cuestionan el ritmo del compromiso.<br>',n19:'Deterioro inmediato de activos: castigo de 250M$. Transparente pero doloroso.<br>',n20:'Deterioro gradual en 5 años. Impacto más suave en los resultados.<br>',n21:'Deterioro postergado. Riesgo de un castigo sorpresa mayor más adelante.<br>',n22:'Se planea la emisión de bono verde. La demanda de inversores ESG es fuerte.<br>',n23:'Se negoció un préstamo vinculado a sostenibilidad. Tasa ligada al desempeño de KPIs.<br>',n24:'Desinversión de activos no esenciales + deuda convencional. Directo pero sin señal ESG.<br>',n25:'Bono verde de 200M EUR emitido con cupón del 4.2%. Fuerte demanda de inversores ESG.<br>',n26:'Bono verde de 100M EUR emitido. Capital ESG moderado obtenido.<br>',n27:'Sin bono verde. Oportunidad perdida de acceso a capital ESG.<br>',n28:'Monetización agresiva de créditos de carbono: 15M$ de ingresos. Riesgo de volatilidad del mercado.<br>',n29:'Ventas moderadas de créditos: 8M$ de ingresos. Reserva mantenida para cumplimiento.<br>',n30:'Créditos retenidos para cumplimiento interno. Sin ingresos de mercado.<br>',n31:'Cabildeo por exenciones. Éxito parcial: exposición reducida a 70M$. Persiste el riesgo político.<br>',n32:'Estrategia de inversión en compensaciones. Exposición neta: 85M$. Mejora la narrativa climática.<br>',n33:'Costos trasladados a los clientes. Margen protegido pero competitividad debilitada.<br>',n34:'Contratos premium de acero verde asegurados con clientes de la UE. Ingreso adicional: 20M$.<br>',n35:'Se inició la inversión en producción en la UE. Alto capex ahora; ingresos exentos de aranceles después.<br>',n36:'Absorbiendo el arancel CBAM. Volumen mantenido pero márgenes comprimidos.<br>',n37:'Se adquirió seguro climático integral. 8M$/año por cobertura completa.<br>',n38:'Seguro climático básico. Eventos mayores cubiertos. 5M$/año.<br>',n39:'Autoasegurado. Prima ahorrada pero el riesgo físico se retiene por completo.<br>',n40:'Daños por inundación en Perú: 25M$. El seguro cubre 20M$. Pérdida neta: 5M$.<br>',n41:'Daños por inundación en Perú: 25M$. El seguro básico cubre 13M$. Pérdida neta: 12M$.<br>',n42:'Daños por inundación en Perú: 25M$. Sin seguro. Pérdida total absorbida.<br>',n43:'Énfasis en el escenario alineado a 1.5C. Fuerte señal de liderazgo climático.<br>',n44:'Ponderación equilibrada de escenarios. Creíble y pragmático.<br>',n45:'Énfasis en 3C. Los escépticos de la junta satisfechos pero los activistas alarmados. Aumenta el riesgo de desinversión.<br>',n46:'Reconstrucción resiliente al clima en Perú. Inversión de 40M$ para protección a largo plazo.<br>',n47:'Reconstrucción estándar + seguro mejorado. Costo de reconstrucción: 25M$.<br>',n48:'Reubicación de la planta de Perú a un sitio de menor riesgo. 60M$ pero elimina la exposición a inundaciones.<br>',n49:'Divulgación máxima ISSB. Elogiada por analistas ESG. Establece el referente del sector.<br>',n50:'Divulgación estándar ISSB. Cumple los requisitos, evita exposición innecesaria.<br>',n51:'Divulgación mínima. Los reguladores señalan vacíos. Se intensifican las críticas de los activistas.<br>',n52:'Estrategia de narrativa dual. El mensaje adaptado resuena con cada audiencia.<br>',n53:'Mensaje ambicioso unificado. Se consolida la marca de liderazgo climático.<br>',n54:'Mensaje conservador. Los acreedores se tranquilizan pero crece la frustración de los activistas.<br>',n55:'Defensa agresiva del capex con datos sobre activos varados evitados y el valor de la prima verde.<br>',n56:'La defensa equilibrada reconoce los costos mientras destaca las ganancias estratégicas.<br>',n57:'Conceder las preocupaciones sobre el momento muestra humildad. Reacciones mixtas.<br>',n58:'El 30% del bono ejecutivo ligado a KPIs climáticos. Fuerte señal de rendición de cuentas.<br>',n59:'Vinculación del 15% del bono a KPIs climáticos. Enfoque equilibrado.<br>',n60:'Sin vinculación climática en la compensación. Los activistas lo ven como un fallo de gobernanza.<br>',n61:'Compromiso de cero neto para 2045. La ambición líder del sector atrae capital ESG.<br>',n62:'Cero neto para 2050. Alineado con París. Creíble y esperado.<br>',n63:'S